```
for each border cell that is 'O':
    mark as temp, enqueue
while queue not empty:
    cell = dequeue
    for each of 4 neighbors:
        if in-bounds and is 'O':
            mark as temp, enqueue
for each cell in board:
    if 'O': set to 'X'
    if temp: set to 'O'
```

code.cpp:
class Solution {
public:
    void solve(vector<vector<char>>& board) {
        int m = board.size();
        if (m == 0) return;
        int n = board[0].size();

        queue<pair<int,int>> q;

        for (int i = 0; i < m; i++) {
            if (board[i][0] == 'O') { board[i][0] = 'T'; q.push({i, 0}); }
            if (board[i][n - 1] == 'O') { board[i][n - 1] = 'T'; q.push({i, n - 1}); }
        }
        for (int j = 0; j < n; j++) {
            if (board[0][j] == 'O') { board[0][j] = 'T'; q.push({0, j}); }
            if (board[m - 1][j] == 'O') { board[m - 1][j] = 'T'; q.push({m - 1, j}); }
        }

        int dx[] = {0, 0, 1, -1};
        int dy[] = {1, -1, 0, 0};

        while (!q.empty()) {
            int x = q.front().first;
            int y = q.front().second;
            q.pop();
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d];
                int ny = y + dy[d];
                if (nx >= 0 && nx < m && ny >= 0 && ny < n && board[nx][ny] == 'O') {
                    board[nx][ny] = 'T';
                    q.push({nx, ny});
                }
            }
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'O') board[i][j] = 'X';
                else if (board[i][j] == 'T') board[i][j] = 'O';
            }
        }
    }
};
